import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction<Record<string, unknown>>;
}

function formatValidationErrors(errors: ErrorObject[]): string {
  return errors
    .map(error => {
      const path = error.instancePath || (error as ErrorObject & {dataPath?: string}).dataPath || '/';
      const params = error.params as Record<string, unknown>;
      if (error.keyword === 'required') {
        const missingPath = `${path === '/' ? '' : path}/${String(params.missingProperty)}`;
        return `property ${missingPath} is required`;
      }
      if (error.keyword === 'type') return `property ${path} must be ${String(params.type)}`;
      return `property ${path} ${error.message ?? 'is invalid'}`;
    })
    .join('; ');
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false, coerceTypes: false, useDefaults: false});
  private readonly validators = new WeakMap<object, ValidateFunction<Record<string, unknown>>>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compile(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  private compile(name: string, schema: Record<string, unknown>): ValidateFunction<Record<string, unknown>> {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    try {
      const validator = this.ajv.compile<Record<string, unknown>>(schema);
      this.validators.set(schema, validator);
      return validator;
    } catch (error) {
      const reason = error instanceof Error ? error.message : 'invalid JSON Schema';
      throw new Error(`Invalid inputSchema for tool ${name}: ${reason}`, {cause: error});
    }
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the registered schema; schema rejection returns a ToolResponse, unknown tools throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition =
      typeof tool.definitionSource === 'function' ? this.resolveDefinition(tool.definitionSource) : undefined;
    const validator = tool.validator ?? this.compile(definition!.name, definition!.inputSchema);
    if (!validator(input)) {
      const details = formatValidationErrors(validator.errors ?? []);
      const result = `Tool input validation failed: ${details}`;
      log.warn('tool', 'input rejected', {name, errors: details});
      return {result};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';
import {jest} from '@jest/globals';

describe('ToolRegistry input validation', () => {
  // ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../specs/hal-engine-tool-input-validation/spec.md#L12))
  it('returns a required-property rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      executor
    );

    const response = await registry.execute('get_weather', {});

    expect({
      resultNamesRequiredLocation: /location.*required/i.test(response.result),
      executorCalls: executor.mock.calls.length,
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  // ([validated by: an unregistered tool name still throws `Unknown tool: <name>`](../../specs/hal-engine-tool-input-validation/spec.md#L15))
  it('throws the unchanged unknown-tool error for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_weather', {})).rejects.toThrow('Unknown tool: missing_weather');
  });

  // ([validated by: valid input with undeclared properties reaches the executor unchanged](../../specs/hal-engine-tool-input-validation/spec.md#L14))
  it('passes valid input with extra properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async (input: Record<string, unknown>) => JSON.stringify(input));
    const input = {location: 'Paris', identifyingNote: 'private'};
    registry.register(
      {
        name: 'pass_through_weather',
        description: 'Reads weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      executor
    );

    await registry.execute('pass_through_weather', input);

    expect(executor.mock.calls).toEqual([[input, undefined]]);
  });

  it('names the full path for a nested required property rejection', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_weather',
        description: 'Reads a nested location',
        inputSchema: {
          type: 'object',
          properties: {
            address: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
          required: ['address'],
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('nested_weather', {address: {}});

    expect(response.result).toEqual(expect.stringMatching(/address.*city|\/address\/city/i));
  });

  // ([validated by: a static tool's inputSchema is compiled at register time and reused on every execute call](../../specs/hal-engine-tool-input-validation/spec.md#L20))
  it('reuses a static schema validator across ten executions', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    const inputSchema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
    };
    registry.register({name: 'cached_weather', description: 'Reads weather', inputSchema}, executor);
    Object.defineProperty(inputSchema, 'properties', {
      enumerable: true,
      get: () => {
        throw new Error('schema was read after registration');
      },
    });

    for (let attempt = 0; attempt < 10; attempt += 1) {
      await registry.execute('cached_weather', {location: 'Paris'});
    }

    expect(executor).toHaveBeenCalledTimes(10);
  });

  // ([validated by: a function-valued source validates each call against its returned schema](../../specs/hal-engine-tool-input-validation/spec.md#L21))
  it('validates function-valued definitions against the schema returned for each call', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    const schemas = [
      {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      {type: 'object', properties: {postalCode: {type: 'number'}}, required: ['postalCode']},
    ];
    let calls = 0;
    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Reads weather with a changing schema',
        inputSchema: schemas[Math.max(0, Math.min(calls++ - 1, schemas.length - 1))],
      }),
      executor
    );

    const first = await registry.execute('dynamic_weather', {location: 'Paris'});
    const second = await registry.execute('dynamic_weather', {postalCode: 75001});

    expect({
      response: {first: first.result, second: second.result},
      executorCalls: executor.mock.calls.length,
    }).toEqual({
      response: {first: 'ok', second: 'ok'},
      executorCalls: 2,
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | Implemented          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property path as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L17), [nested path](../../src/orchestration/tools/registry.test.ts#L52)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L48)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with extra properties reaches the executor unchanged](../../src/orchestration/tools/registry.test.ts#L34)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake ([validated by: throws the unchanged unknown-tool error for an unregistered name](../../src/orchestration/tools/registry.test.ts#L27)).

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L97)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: reuses a static schema validator across ten executions](../../src/orchestration/tools/registry.test.ts#L79)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates function-valued definitions against the schema returned for each call](../../src/orchestration/tools/registry.test.ts#L102)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L116)).
